create extension if not exists pgcrypto;
create type source_type as enum ('auction','government_surplus','municipal_surplus','liquidation','insolvency_notice','bankruptcy_notice','receivership','tender','rfp','private_sale','unknown');
create type asset_type as enum ('real_estate','vehicles','machinery','equipment','inventory','intellectual_property','receivables','business_sale','licenses','leases','fixtures','scrap','vessels','aircraft','technology_assets','unknown');
create type confidence_level as enum ('high','medium','low','unknown'); create type review_status as enum ('inbox','needs_review','reviewed','dismissed'); create type duplicate_status as enum ('unique','possible_duplicate','duplicate_confirmed','duplicate_rejected'); create type deadline_status as enum ('unknown','estimated','confirmed','extended','expired','cancelled'); create type outcome_status as enum ('ignored','reviewed','pursued','contacted','bid','won','lost','expired'); create type score_band as enum ('excellent','strong','watch','weak','ignore','needs_review');
create table sources (id uuid primary key default gen_random_uuid(),name text not null,source_type source_type not null default 'unknown',jurisdiction_country text,jurisdiction_region text,base_url text,robots_policy_notes text,terms_notes text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table import_batches (id uuid primary key default gen_random_uuid(),filename text,row_count integer not null default 0,valid_count integer not null default 0,invalid_count integer not null default 0,status text not null default 'created',error_report jsonb not null default '[]'::jsonb,created_at timestamptz not null default now());
create table source_snapshots (id uuid primary key default gen_random_uuid(),source_id uuid references sources(id) on delete set null,original_url text,normalized_url text,captured_title text,captured_text text not null,content_hash text not null,parser_version text not null default 'v0.1',captured_at timestamptz not null default now(),unique(normalized_url, content_hash));
create table raw_signals (id uuid primary key default gen_random_uuid(),source_id uuid references sources(id) on delete set null,source_snapshot_id uuid references source_snapshots(id) on delete set null,import_batch_id uuid references import_batches(id) on delete set null,original_url text,normalized_url text,title text not null,raw_text text,extracted_company_name text,extracted_asset_type asset_type not null default 'unknown',extracted_source_type source_type not null default 'unknown',extracted_location text,extracted_deadline timestamptz,extracted_estimated_value numeric,currency text not null default 'USD',extraction_status text not null default 'parsed',review_status review_status not null default 'inbox',duplicate_status duplicate_status not null default 'unique',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table companies (id uuid primary key default gen_random_uuid(),name text not null,normalized_name text not null,jurisdiction_country text,jurisdiction_region text,created_at timestamptz not null default now(),unique(normalized_name));
create table assets (id uuid primary key default gen_random_uuid(),raw_signal_id uuid not null references raw_signals(id) on delete cascade,company_id uuid references companies(id) on delete set null,asset_type asset_type not null default 'unknown',title text not null,description text,location_text text,jurisdiction_country text,jurisdiction_region text,estimated_asset_value numeric,asking_price numeric,current_bid numeric,bid_increment numeric,buyer_premium numeric,taxes_fees_estimate numeric,removal_cost_estimate numeric,shipping_cost_estimate numeric,storage_cost_estimate numeric,total_landed_cost_estimate numeric,expected_resale_value numeric,expected_margin numeric,currency text not null default 'USD',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table opportunities (id uuid primary key default gen_random_uuid(),raw_signal_id uuid not null references raw_signals(id) on delete cascade,asset_id uuid not null references assets(id) on delete cascade,status outcome_status not null default 'reviewed',score_band score_band not null default 'needs_review',current_score integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table evidence_items (id uuid primary key default gen_random_uuid(),raw_signal_id uuid not null references raw_signals(id) on delete cascade,source_snapshot_id uuid references source_snapshots(id) on delete set null,evidence_type text not null default 'source_text',label text not null,value text,source_text_excerpt text,content_hash text,created_at timestamptz not null default now());
create table parser_confidence (id uuid primary key default gen_random_uuid(),raw_signal_id uuid not null references raw_signals(id) on delete cascade,field_name text not null,confidence confidence_level not null default 'unknown',reason text,created_at timestamptz not null default now(),unique(raw_signal_id, field_name));
create table duplicate_candidates (id uuid primary key default gen_random_uuid(),raw_signal_id uuid not null references raw_signals(id) on delete cascade,candidate_signal_id uuid not null references raw_signals(id) on delete cascade,duplicate_score numeric not null,reasons jsonb not null default '[]'::jsonb,status duplicate_status not null default 'possible_duplicate',created_at timestamptz not null default now(),unique(raw_signal_id, candidate_signal_id));
create table deadlines (id uuid primary key default gen_random_uuid(),opportunity_id uuid not null references opportunities(id) on delete cascade,deadline_at timestamptz,deadline_timezone text,deadline_status deadline_status not null default 'unknown',deadline_confidence confidence_level not null default 'unknown',deadline_source_text text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table watchlist_items (id uuid primary key default gen_random_uuid(),opportunity_id uuid not null references opportunities(id) on delete cascade,notes text,created_at timestamptz not null default now(),unique(opportunity_id));
create table pursuit_notes (id uuid primary key default gen_random_uuid(),opportunity_id uuid not null references opportunities(id) on delete cascade,note_text text not null,counterparty text,contact_date date,next_action text,bid_amount numeric,asking_price numeric,response text,attachment_metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table outcomes (id uuid primary key default gen_random_uuid(),opportunity_id uuid not null references opportunities(id) on delete cascade,status outcome_status not null,amount numeric,notes text,created_at timestamptz not null default now());
create table scoring_rules (id uuid primary key default gen_random_uuid(),version text not null unique,active boolean not null default false,weights jsonb not null,created_at timestamptz not null default now());
create table opportunity_scores (id uuid primary key default gen_random_uuid(),opportunity_id uuid not null references opportunities(id) on delete cascade,scoring_rule_version text not null,total_score integer not null,score_band score_band not null,components jsonb not null,created_at timestamptz not null default now());
create table score_explanations (id uuid primary key default gen_random_uuid(),opportunity_score_id uuid not null references opportunity_scores(id) on delete cascade,component text not null,score integer not null,explanation text not null,created_at timestamptz not null default now());
create table audit_events (id uuid primary key default gen_random_uuid(),entity_type text not null,entity_id uuid,action text not null,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index idx_raw_signals_review_status on raw_signals(review_status); create index idx_raw_signals_duplicate_status on raw_signals(duplicate_status); create index idx_raw_signals_source_type on raw_signals(extracted_source_type); create index idx_assets_asset_type on assets(asset_type); create index idx_opportunities_score on opportunities(current_score); create index idx_deadlines_deadline_at on deadlines(deadline_at); create index idx_watchlist_opportunity on watchlist_items(opportunity_id);
